import numpy as np, wfdb, warnings, json
warnings.filterwarnings('ignore')
import neurokit2 as nk
for eid in ['104821039','106885519','104882441','101515306']:
    rec=wfdb.rdrecord('ecgall/'+eid); fs=rec.fs
    sig=np.nan_to_num(rec.p_signal)
    print('==',eid)
    for lead in ['II','V5','V2']:
        x=nk.ecg_clean(sig[:,rec.sig_name.index(lead)],sampling_rate=fs)
        _,info=nk.ecg_peaks(x,sampling_rate=fs); rp=info['ECG_R_Peaks']
        for m in ['dwt','peak']:
            try:
                _,w=nk.ecg_delineate(x,rpeaks=rp,sampling_rate=fs,method=m)
                on=np.array(w['ECG_R_Onsets'],dtype=float); off=np.array(w['ECG_T_Offsets'],dtype=float)
                qt=[]
                for o,t in zip(on,off):
                    if not np.isnan(o) and not np.isnan(t) and 200<(t-o)/fs*1000<700: qt.append((t-o)/fs*1000)
                rr=np.median(np.diff(rp))/fs
                print(f"  {lead} {m}: qt_med={np.median(qt) if qt else None} n={len(qt)} qtc={(np.median(qt)/np.sqrt(rr)) if qt else None}")
            except Exception as e: print('  ',lead,m,'err',e)
