import json,base64,collections,re,sys
pats={p['id']:p for p in json.load(open('patients.txt'))['resources']}
notes=[json.loads(l) for l in open('DocumentReference.ndjson')]
notes=[n for n in notes if 'subject' in n]
byp=collections.defaultdict(list)
for n in notes:
    n['txt']=base64.b64decode(n['content'][0]['attachment']['data']).decode()
    byp[n['subject']['reference'].split('/')[-1]].append(n)
meds={}
for l in open('Medication.ndjson'):
    r=json.loads(l)
    for i in r.get('identifier',[]):
        if 'medication-name' in i['system']: meds[r['id']]=i['value']
clinenc=set(json.load(open('clinenc.json')))
mrs=collections.defaultdict(list)
for l in open('MedicationRequest.ndjson'):
    m=json.loads(l)
    if m.get('encounter',{}).get('reference','').split('/')[-1] in clinenc:
        mrs[m['subject']['reference'].split('/')[-1]].append(m)
conds=collections.defaultdict(list)
encs={}
for l in open('Encounter.ndjson'):
    e=json.loads(l); encs[e['id']]=e.get('period',{}).get('start','')[:10]
for l in open('Condition.ndjson'):
    c=json.loads(l); conds[c['subject']['reference'].split('/')[-1]].append(c)
ecg=collections.defaultdict(list)
for e in json.load(open('ecgs.json'))['ecgs']: ecg[e['patient']].append(e)
BOIL=re.compile(r'^(Seen in cardiology|Cardiology clinic follow|Clinic visit, cardiology|\d+-year-old|BP \d+|Signed:|$|Continue current regimen|No changes today|Plan as above)')
def show(pid):
    p=[k for k in pats if k.startswith(pid)][0]
    pt=pats[p]
    print('='*100)
    print(f"PATIENT {p} dob={pt['birthDate']} {pt['gender']} deceased={pt.get('deceasedDateTime')}")
    afc=[c for c in conds[p] if re.search('fibrill|flutter',c['code']['coding'][0].get('display',''),re.I)]
    for c in afc:
        print('  AFCOND',c['id'],c['code']['coding'][0]['code'],c['code']['coding'][0]['display'],encs.get(c.get('encounter',{}).get('reference','').split('/')[-1]))
    rel=[c['code']['coding'][0].get('display','') for c in conds[p]]
    keys=['heart failure','cardiomyopathy','hypertens','diabet','stroke','infarction','cerebral','ischemic','atheroscler','vascular','emboli','hemorrhag','bleed','ulcer','aneurysm','fall','anemia','thrombocyt','coagul','myocardial','peripheral','aortic']
    seen=set()
    for r in rel:
        for k in keys:
            if k in r.lower() and r not in seen:
                seen.add(r); print('   COND:',r); break
    print('  CLINIC ORDERS:')
    for m in sorted(mrs[p],key=lambda m:m['authoredOn']):
        nm=meds.get(m.get('medicationReference',{}).get('reference','').split('/')[-1])
        di=m.get('dosageInstruction',[{}])[0]
        dq=di.get('doseAndRate',[{}])[0].get('doseQuantity',{})
        print(f"    {m['authoredOn'][:10]} {nm} {dq.get('value')}{dq.get('unit')} id={m['id']}")
    print('  ECGS:',[(e['time'][:16],e['ecg']) for e in sorted(ecg[p],key=lambda x:x['time'])])
    print('  NOTES:')
    for n in sorted(byp[p],key=lambda n:n['date']):
        role=[e.get('valueCode') for e in n.get('extension',[]) if 'author-role' in e['url']]
        print(f"   --{n['date'][:16]} {role[0] if role else '?'} {n.get('author',[{}])[0].get('display')} {n['id']}")
        for line in n['txt'].split('\n'):
            if not BOIL.match(line.strip()): print('      ',line.strip())
for a in sys.argv[1:]:
    show(a.rstrip(','))
EOF
