cd /tmp && python3 - <<'EOF'
import json,collections
meds={}
for l in open('Medication.ndjson'):
    r=json.loads(l)
    for i in r.get('identifier',[]):
        if 'medication-name' in i['system']: meds[r['id']]=i['value']
clinenc=set(json.load(open('clinenc.json')))
rows=collections.defaultdict(list)
for l in open('MedicationRequest.ndjson'):
    m=json.loads(l)
    if m.get('encounter',{}).get('reference','').split('/')[-1] not in clinenc: continue
    nm=(meds.get(m.get('medicationReference',{}).get('reference','').split('/')[-1]) or '')
    if 'warfarin' in nm.lower():
        di=m.get('dosageInstruction',[{}])[0]
        dq=di.get('doseAndRate',[{}])[0].get('doseQuantity',{})
        rows[m['subject']['reference'].split('/')[-1]].append((m['authoredOn'][:10],dq.get('value')))
for k,v in sorted(rows.items()): print(k[:8],sorted(v))
EOF
